STATEMENTS = (
    "CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)))",
    "CREATE TABLE document_sequences (kind TEXT NOT NULL,year INTEGER NOT NULL,value INTEGER NOT NULL,PRIMARY KEY(kind,year))",
    "CREATE TABLE quotes (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,client_id INTEGER NOT NULL REFERENCES clients(id),client_snapshot TEXT NOT NULL,items TEXT NOT NULL,freight_cents INTEGER NOT NULL CHECK(freight_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),valid_until TEXT,notes TEXT NOT NULL,created_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('pending','approved','rejected')),reason TEXT NOT NULL DEFAULT '',operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,quote_id INTEGER UNIQUE REFERENCES quotes(id),client_id INTEGER NOT NULL REFERENCES clients(id),client_snapshot TEXT NOT NULL,freight_cents INTEGER NOT NULL CHECK(freight_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),notes TEXT NOT NULL,due_on TEXT,created_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('approved','cancelled')),operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),variant_id INTEGER REFERENCES variants(id),description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),snapshot TEXT NOT NULL,fulfillment TEXT NOT NULL CHECK(fulfillment IN('stock','production')),reservation_id INTEGER UNIQUE REFERENCES reservations(id))",
    "CREATE TABLE order_fulfillment (item_id INTEGER PRIMARY KEY REFERENCES order_items(id),variant_id INTEGER NOT NULL REFERENCES variants(id))",
    "CREATE TABLE installments (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),due_on TEXT,received_cents INTEGER NOT NULL DEFAULT 0 CHECK(received_cents>=0 AND received_cents<=amount_cents))",
    "CREATE TABLE client_credit (id INTEGER PRIMARY KEY AUTOINCREMENT,client_id INTEGER NOT NULL REFERENCES clients(id),order_id INTEGER NOT NULL REFERENCES orders(id),direction TEXT NOT NULL CHECK(direction IN('in','out')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),created_at TEXT NOT NULL,reason TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),fee_cents INTEGER NOT NULL CHECK(fee_cents>=0),net_cents INTEGER NOT NULL CHECK(net_cents>=0),paid_on TEXT NOT NULL,method TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('cash','credit')),credit_id INTEGER UNIQUE REFERENCES client_credit(id),created_at TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE payment_allocations (id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER NOT NULL REFERENCES payments(id),item_id INTEGER REFERENCES order_items(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0))",
    "CREATE TABLE installment_allocations (payment_id INTEGER NOT NULL REFERENCES payments(id),installment_id INTEGER NOT NULL REFERENCES installments(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),PRIMARY KEY(payment_id,installment_id))",
    "CREATE TABLE cancellations (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id),reason TEXT NOT NULL,refund_cents INTEGER NOT NULL CHECK(refund_cents>=0),credit_cents INTEGER NOT NULL CHECK(credit_cents>=0),retained_cents INTEGER NOT NULL CHECK(retained_cents>=0),created_at TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE refunds (id INTEGER PRIMARY KEY AUTOINCREMENT,cancellation_id INTEGER NOT NULL UNIQUE REFERENCES cancellations(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),paid_on TEXT NOT NULL,method TEXT NOT NULL,reason TEXT NOT NULL)",
    "CREATE TABLE order_returns (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),piece_id INTEGER NOT NULL REFERENCES pieces(id),created_at TEXT NOT NULL,condition TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE,UNIQUE(order_id,piece_id))",
    "CREATE TABLE order_item_calculations (item_id INTEGER NOT NULL REFERENCES order_items(id),calculation_id INTEGER NOT NULL UNIQUE REFERENCES calculations(id),created_at TEXT NOT NULL,PRIMARY KEY(item_id,calculation_id))",
    "CREATE TABLE sales_attachments (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER REFERENCES orders(id),quote_id INTEGER REFERENCES quotes(id),item_id INTEGER REFERENCES order_items(id),item_index INTEGER,kind TEXT NOT NULL,path TEXT NOT NULL,original_name TEXT NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((order_id IS NOT NULL)+(quote_id IS NOT NULL)=1))",
    "CREATE TABLE deliveries (order_id INTEGER PRIMARY KEY REFERENCES orders(id),state TEXT NOT NULL CHECK(state IN('waiting','sent','delivered')),mode TEXT NOT NULL CHECK(mode IN('pickup','shipping')),carrier TEXT NOT NULL DEFAULT '',tracking TEXT NOT NULL DEFAULT '',sent_on TEXT,delivered_on TEXT,proof_id INTEGER REFERENCES sales_attachments(id))",
    "CREATE TABLE sales_documents (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER REFERENCES orders(id),quote_id INTEGER REFERENCES quotes(id),version INTEGER NOT NULL,path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((order_id IS NOT NULL)+(quote_id IS NOT NULL)=1))",
    "CREATE UNIQUE INDEX order_document_versions ON sales_documents(order_id,version) WHERE order_id IS NOT NULL",
    "CREATE UNIQUE INDEX quote_document_versions ON sales_documents(quote_id,version) WHERE quote_id IS NOT NULL",
)
